S=/tmp/claude-0/-tmp-eff-2y16yhvk-work/a4eb1cb7-866c-5bbf-8d81-a8d5acd83be3/scratchpad; cat > $S/dashboard.json <<'EOF'
{
  "title": "EFF-08d6be70 Web logs overview",
  "panels": [
    {
      "grid": {"x": 0, "y": 0, "w": 12, "h": 6},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Total requests",
        "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
        "metrics": [{"type": "primary", "operation": "count"}]
      }
    },
    {
      "grid": {"x": 12, "y": 0, "w": 12, "h": 6},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Average response size (bytes)",
        "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
        "metrics": [{"type": "primary", "operation": "average", "field": "bytes"}]
      }
    },
    {
      "grid": {"x": 24, "y": 0, "w": 12, "h": 6},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Unique client IPs",
        "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
        "metrics": [{"type": "primary", "operation": "unique_count", "field": "clientip"}]
      }
    },
    {
      "grid": {"x": 36, "y": 0, "w": 12, "h": 6},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "5xx responses",
        "data_source": {"type": "esql", "query": "FROM kibana_sample_data_logs | WHERE response.keyword LIKE \"5*\" | STATS count = COUNT()"},
        "metrics": [{"type": "primary", "field": "count"}]
      }
    },
    {
      "grid": {"x": 0, "y": 6, "w": 24, "h": 12},
      "type": "vis",
      "config": {
        "type": "xy",
        "title": "Requests over time",
        "layers": [
          {
            "type": "line",
            "data_source": {"type": "esql", "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"},
            "x": {"column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)"},
            "y": [{"column": "count"}]
          }
        ]
      }
    },
    {
      "grid": {"x": 24, "y": 6, "w": 24, "h": 12},
      "type": "vis",
      "config": {
        "type": "xy",
        "title": "Requests by response code",
        "layers": [
          {
            "type": "bar",
            "data_source": {"type": "esql", "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY response.keyword | SORT count DESC | LIMIT 10"},
            "x": {"column": "response.keyword"},
            "y": [{"column": "count"}]
          }
        ]
      }
    }
  ]
}
EOF
curl -sS -X POST -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "kbn-xsrf: true" -H "Content-Type: application/json" "$KIBANA_URL/api/dashboards" --data-binary @$S/dashboard.json > $S/dashboard_resp.json; python3 -c "
import json;d=json.load(open('$S/dashboard_resp.json'))
print(json.dumps(d,indent=1)[:1500] if 'id' in d else d)"

